/**
 * Tomada de turno da conversa por voz (lógica pura, sem áudio nem DOM, para
 * ser testada em Node). Recebe eventos com horário e devolve ações:
 *
 *   voz(nivel, t)          energia do microfone a cada quadro (VAD)
 *   texto(parcial, final, t)   reconhecimento em streaming
 *   iaComecou(t) / iaTerminou(t)
 *
 * Ações emitidas: "fim_de_turno" (enviar resposta), "interromper_ia"
 * (parar a voz e descartar o áudio pendente), "silencio_longo" (oferecer
 * ajuda sem penalizar) e "silencio_sem_resposta" (enviar turno vazio).
 */

// Pedido de tempo para pensar: a IA aguarda (não é a resposta).
export const PENSANDO = /^(hum+|hmm+|é+|então|deixa eu pensar|deixe-me pensar|deixa eu lembrar|deixa eu ver|um (momento|minuto|segundo|instante)|só um (momento|minuto|segundo|instante)|peraí|pera aí|let me think|one (moment|second)|déjame pensar|un momento)[\s.,!…]*$/i;

const CONTINUACAO = /\b(e|então|entao|porque|mas|tipo|né|ne|ou|que|aí|ai|and|so|because|but|or|y|pero|porque|entonces)\s*$/i;

export const PADROES = {
  limiarVoz: 0.02,          // RMS a partir do qual há fala (calibrado no teste técnico)
  fimDeFalaMs: 1300,        // silêncio após a última fala para encerrar o turno
  fimDeFalaLongaMs: 1800,   // resposta longa (mais de 30 palavras): pausas de raciocínio no meio
  fimDeFalaContinuacaoMs: 2400, // quando a frase termina em conectivo ("e…", "porque…")
  pensandoMs: 20000,        // "deixa eu pensar": aguarda sem tratar o silêncio como resposta
  interrupcaoMs: 350,       // fala contínua do candidato que interrompe a IA
  fatorDuranteIa: 2,        // limiar mais alto enquanto a IA fala (eco do alto-falante)
  silencioLongoMs: 25000,   // oferece repetir/reformular
  silencioSemRespostaMs: 60000,
};

export class TomadaDeTurno {
  constructor(opcoes = {}) {
    this.o = { ...PADROES, ...opcoes };
    this.iaFalando = false;
    this.falando = false;
    this.inicioFala = null;
    this.ultimaVoz = null;
    this.textoFinal = "";
    this.parcial = "";
    this.esperandoDesde = null; // fim da pergunta da IA
    this.avisouSilencio = false;
    this.ultimoFimDeFala = null;
  }

  calibrar(ruidoMedio) {
    this.o.limiarVoz = Math.max(PADROES.limiarVoz * 0.6, Math.min(0.08, ruidoMedio * 3));
    return this.o.limiarVoz;
  }

  iaComecou(t) {
    this.iaFalando = true;
    this.esperandoDesde = null;
    return [];
  }

  iaTerminou(t) {
    this.iaFalando = false;
    this.esperandoDesde = t;
    this.avisouSilencio = false;
    return [];
  }

  texto(parcial, final, t) {
    if (final) this.textoFinal = `${this.textoFinal} ${final}`.trim();
    this.parcial = parcial ?? "";
    if ((final || parcial) && !this.iaFalando) this.ultimaVoz = t;
    return [];
  }

  /** Um quadro de áudio (~50 ms). */
  voz(nivel, t) {
    const acoes = [];
    const ha = nivel >= this.o.limiarVoz * (this.iaFalando ? this.o.fatorDuranteIa : 1);
    if (ha) {
      if (!this.falando) {
        this.falando = true;
        this.inicioFala = t;
      }
      this.ultimaVoz = t;
      // Interrupção: fala contínua do candidato enquanto a IA fala.
      if (this.iaFalando && t - this.inicioFala >= this.o.interrupcaoMs) {
        this.iaFalando = false;
        acoes.push({ tipo: "interromper_ia", t });
      }
    } else if (this.falando && t - this.ultimaVoz > 200) {
      this.falando = false;
      this.ultimoFimDeFala = this.ultimaVoz;
    }

    const temTexto = (this.textoFinal + this.parcial).trim().length > 0;
    if (!this.iaFalando && !this.falando && temTexto && this.ultimaVoz != null) {
      const atual = `${this.textoFinal} ${this.parcial}`.trim();
      const pensando = PENSANDO.test(atual);
      if (pensando && !this.avisouPensando) {
        this.avisouPensando = true;
        acoes.push({ tipo: "pensando", t });
      }
      const espera = pensando ? this.o.pensandoMs : CONTINUACAO.test(atual) ? this.o.fimDeFalaContinuacaoMs : atual.split(/\s+/).length > 30 ? this.o.fimDeFalaLongaMs : this.o.fimDeFalaMs;
      if (t - this.ultimaVoz >= espera) {
        const texto = `${this.textoFinal} ${this.parcial}`.trim();
        acoes.push({ tipo: "fim_de_turno", texto, fimDaFala: this.ultimaVoz, t });
        this.reiniciar();
      }
    }

    if (!this.iaFalando && !temTexto && !this.falando && this.esperandoDesde != null) {
      const calado = t - this.esperandoDesde;
      if (!this.avisouSilencio && calado >= this.o.silencioLongoMs) {
        this.avisouSilencio = true;
        acoes.push({ tipo: "silencio_longo", t });
      }
      if (calado >= this.o.silencioSemRespostaMs) {
        this.esperandoDesde = null;
        acoes.push({ tipo: "silencio_sem_resposta", t });
      }
    }
    return acoes;
  }

  reiniciar() {
    this.avisouPensando = false;
    this.textoFinal = "";
    this.parcial = "";
    this.falando = false;
    this.inicioFala = null;
    this.ultimaVoz = null;
    this.esperandoDesde = null;
  }
}

/** Divide o texto que chega em streaming em frases prontas para a voz. */
export class Frasear {
  constructor() {
    this.buf = "";
  }
  adicionar(pedaco) {
    this.buf += pedaco;
    const prontas = [];
    let m;
    while ((m = this.buf.match(/^([\s\S]*?[.!?…:])\s+/))) {
      if (m[1].trim()) prontas.push(m[1].trim());
      this.buf = this.buf.slice(m[0].length);
    }
    return prontas;
  }
  fim() {
    const resto = this.buf.trim();
    this.buf = "";
    return resto ? [resto] : [];
  }
}

/** p50/p95 de uma lista de medições (ms). */
export function percentis(valores) {
  const v = valores.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  const p = (q) => (v.length ? Math.round(v[Math.min(v.length - 1, Math.floor(q * v.length))]) : null);
  return { n: v.length, p50: p(0.5), p95: p(0.95) };
}

/**
 * Texto que vai para a voz: só a fala, sem aspas, marcações, listas ou
 * fragmentos técnicos que a síntese leria de forma artificial.
 */
export function paraFala(texto) {
  return String(texto ?? "")
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/[{}[\]<>`*_#|]/g, " ")
    .replace(/[“”"«»]/g, "")
    .replace(/\s+[—–]\s+/g, ", ")
    .replace(/\s*:\s*$/g, ".")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * Agrupa a fala que chega em streaming em no máximo dois trechos: a primeira
 * frase (para a voz começar cedo) e todo o restante de uma vez (com a
 * primeira como contexto), para a entonação não reiniciar a cada frase.
 * Uma primeira frase muito curta ("Claro.") espera a seguinte.
 */
export class Trechos {
  constructor() {
    this.f = new Frasear();
    this.primeiro = null;
    this.resto = [];
  }
  adicionar(pedaco) {
    const prontos = [];
    for (const frase of this.f.adicionar(pedaco)) {
      if (this.primeiro == null) {
        const acumulado = [...this.resto, frase].join(" ");
        if (acumulado.split(/\s+/).length < 5) {
          this.resto.push(frase);
          continue;
        }
        this.primeiro = paraFala(acumulado);
        this.resto = [];
        prontos.push({ texto: this.primeiro, anterior: "", proximo: "" });
      } else this.resto.push(frase);
    }
    return prontos;
  }
  fim() {
    const resto = paraFala([...this.resto, ...this.f.fim()].join(" "));
    if (!resto) return [];
    if (this.primeiro == null) return [{ texto: resto, anterior: "", proximo: "" }];
    return [{ texto: resto, anterior: this.primeiro, proximo: "" }];
  }
}
