/**
 * Cliente da Edge Function interview-sala. Só envia o token do convite; nada
 * de chave de serviço ou de IA no navegador do candidato.
 */
// A função roda na região do banco (cada turno faz várias consultas): sem isso,
// ela rodaria perto do candidato e cada consulta cruzaria o continente.
const REGIAO = __SUPABASE_REGIAO__;
const FUNCAO = `${__SUPABASE_URL__}/functions/v1/interview-sala${REGIAO ? `?forceFunctionRegion=${REGIAO}` : ""}`;
const CHAVE = __SUPABASE_PUBLISHABLE_KEY__;

export class ErroSala extends Error {
  constructor(motivo, status) {
    super(motivo);
    this.status = status;
  }
}

const cabecalhos = (extra = {}) => ({ apikey: CHAVE, ...extra });

export function criarApi(token) {
  async function post(corpo, { tentativas = 3 } = {}) {
    let ultimo;
    for (let i = 0; i < tentativas; i++) {
      try {
        const r = await fetch(FUNCAO, { method: "POST", headers: cabecalhos({ "content-type": "application/json" }), body: JSON.stringify({ token, ...corpo }) });
        const d = await r.json().catch(() => ({}));
        if (!r.ok || d.ok === false) throw new ErroSala(d.motivo ?? "Falha de comunicação.", r.status);
        return d;
      } catch (e) {
        ultimo = e;
        // Erros do servidor com motivo claro (4xx) não adiantam repetir.
        if (e instanceof ErroSala && e.status >= 400 && e.status < 500) throw e;
        await new Promise((r) => setTimeout(r, 400 * 2 ** i));
      }
    }
    throw ultimo instanceof ErroSala ? ultimo : new ErroSala("Sem conexão com o servidor. Verifique a internet; suas respostas salvas não se perdem.", 0);
  }

  return {
    contexto: () => post({ acao: "contexto" }),
    iniciar: (o) => post({ acao: "iniciar", ...o }, { tentativas: 1 }),
    retomar: () => post({ acao: "retomar" }),
    pausar: () => post({ acao: "pausar" }),
    continuar: () => post({ acao: "continuar" }),
    encerrar: () => post({ acao: "encerrar" }),
    ajuda: (mensagem) => post({ acao: "ajuda", mensagem }),
    agendar: (inicio, fuso) => post({ acao: "agendar", inicio, fuso }),
    pesquisa: (o) => post({ acao: "pesquisa", ...o }),
    solicitarExclusao: () => post({ acao: "solicitar_exclusao" }),
    evento: (tipo, dados) => post({ acao: "evento", tipo, dados }, { tentativas: 1 }).catch(() => {}),
    sttToken: () => post({ acao: "stt_token" }),

    async stt(blob, idioma) {
      const f = new FormData();
      f.append("token", token);
      f.append("acao", "stt");
      f.append("idioma", idioma);
      f.append("audio", blob, "fala.webm");
      const r = await fetch(FUNCAO, { method: "POST", headers: cabecalhos(), body: f });
      const d = await r.json().catch(() => ({}));
      if (!r.ok || !d.ok) throw new ErroSala(d.motivo ?? "Falha na transcrição.", r.status);
      return d;
    },

    async ttsTeste(velocidade = 1) {
      const r = await fetch(FUNCAO, { method: "POST", headers: cabecalhos({ "content-type": "application/json" }), body: JSON.stringify({ token, acao: "tts_teste", velocidade }) });
      if (!r.ok) throw new ErroSala("Falha na voz.", r.status);
      return r.blob();
    },

    async tts({ texto, anterior = "", proximo = "", velocidade = 1 }, signal) {
      const r = await fetch(FUNCAO, { method: "POST", signal, headers: cabecalhos({ "content-type": "application/json" }), body: JSON.stringify({ token, acao: "tts", texto, anterior, proximo, velocidade }) });
      if (!r.ok) throw new ErroSala("Falha na voz.", r.status);
      return r.blob();
    },

    /**
     * Envia a resposta e recebe a fala seguinte em streaming (SSE).
     * `aoTexto(pedaço)` a cada trecho; resolve com o evento "fim".
     * Pode ser cancelado com `signal` (interrupção); se a conexão cair,
     * reenviar com o mesmo `seqBase` devolve a fala já processada.
     */
    async turno({ texto, seqBase, falhaAudio = false, confiancaStt = null, voz = false, velocidade = 1, signal, aoInicio, aoTexto, aoAudio, aoAudioFalha }) {
      const r = await fetch(FUNCAO, {
        method: "POST",
        signal,
        headers: cabecalhos({ "content-type": "application/json" }),
        body: JSON.stringify({ token, acao: "turno", texto, seqBase, falhaAudio, confiancaStt, voz, velocidade }),
      });
      if (!r.headers.get("content-type")?.includes("event-stream")) {
        const d = await r.json().catch(() => ({}));
        throw new ErroSala(d.motivo ?? "Falha ao enviar a resposta.", r.status);
      }
      const leitor = r.body.pipeThrough(new TextDecoderStream()).getReader();
      let buf = "";
      let fim = null;
      for (;;) {
        const { value, done } = await leitor.read();
        if (done) break;
        buf += value;
        let i;
        while ((i = buf.indexOf("\n\n")) >= 0) {
          const bloco = buf.slice(0, i);
          buf = buf.slice(i + 2);
          const evento = /^event: (\w+)/m.exec(bloco)?.[1];
          const dados = JSON.parse(/^data: (.*)$/m.exec(bloco)?.[1] ?? "{}");
          if (evento === "inicio") aoInicio?.(dados);
          else if (evento === "delta") aoTexto?.(dados.t);
          else if (evento === "audio") aoAudio?.(dados);
          else if (evento === "audio_falha") aoAudioFalha?.(dados);
          else if (evento === "fim") fim = dados;
          else if (evento === "erro") throw new ErroSala(dados.motivo, dados.recarregar ? 409 : 500);
        }
      }
      if (!fim) throw new ErroSala("A resposta foi interrompida. Reenviando…", 0);
      return fim;
    },
  };
}
