/**
 * Voz da sala: microfone com medidor de nível (VAD), reconhecimento de fala
 * (STT) e síntese (TTS) por adaptadores substituíveis.
 *
 * STT:  navegador (Web Speech, streaming local; Chrome/Edge/Safari)
 *       · servidor_whisper (trecho por fala, Groq Whisper via interview-sala)
 *       · deepgram (streaming por WebSocket, token temporário do servidor)
 * TTS:  navegador (speechSynthesis) · servidor (ElevenLabs em streaming)
 *
 * Cada adaptador expõe a mesma interface; a sala escolhe pelo que o
 * navegador suporta e pelo que o servidor declara configurado.
 */

export async function abrirMicrofone() {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  const fonte = ctx.createMediaStreamSource(stream);
  const analisador = ctx.createAnalyser();
  analisador.fftSize = 1024;
  fonte.connect(analisador);
  const buf = new Float32Array(analisador.fftSize);
  return {
    stream,
    ctx,
    /** RMS atual (0–1). */
    nivel() {
      analisador.getFloatTimeDomainData(buf);
      let s = 0;
      for (const x of buf) s += x * x;
      return Math.sqrt(s / buf.length);
    },
    mudo(sim) {
      for (const t of stream.getAudioTracks()) t.enabled = !sim;
    },
    fechar() {
      for (const t of stream.getTracks()) t.stop();
      ctx.close().catch(() => {});
    },
  };
}

/** Mede o ruído de fundo por `ms` (para calibrar o limiar de fala). */
export async function medirRuido(mic, ms = 1500) {
  const amostras = [];
  const fim = performance.now() + ms;
  while (performance.now() < fim) {
    amostras.push(mic.nivel());
    await new Promise((r) => setTimeout(r, 50));
  }
  amostras.sort((a, b) => a - b);
  return amostras[Math.floor(amostras.length / 2)] ?? 0;
}

const LOCALE = { pt: "pt-BR", en: "en-US", es: "es-ES" };

// ─── STT ──────────────────────────────────────────────────────────────────

export const sttNavegadorSuportado = () => Boolean(window.SpeechRecognition || window.webkitSpeechRecognition);

/** Reconhecimento do navegador, contínuo e com resultados parciais. */
export function sttNavegador({ idioma, aoTexto, aoErro }) {
  const R = window.SpeechRecognition || window.webkitSpeechRecognition;
  let rec = null;
  let ativo = false;
  let lang = LOCALE[idioma] ?? "pt-BR";
  const iniciar = () => {
    rec = new R();
    rec.lang = lang;
    rec.continuous = true;
    rec.interimResults = true;
    rec.maxAlternatives = 1;
    rec.onresult = (ev) => {
      let parcial = "";
      let final = "";
      let confianca = null;
      for (let i = ev.resultIndex; i < ev.results.length; i++) {
        const r = ev.results[i];
        if (r.isFinal) {
          final += r[0].transcript;
          confianca = r[0].confidence || null;
        } else parcial += r[0].transcript;
      }
      aoTexto({ parcial: parcial.trim(), final: final.trim(), confianca });
    };
    rec.onerror = (e) => {
      if (["no-speech", "aborted"].includes(e.error)) return;
      aoErro?.(e.error);
    };
    // O navegador encerra sozinho depois de um tempo: reabre enquanto ativo.
    rec.onend = () => ativo && setTimeout(() => ativo && iniciar(), 100);
    rec.start();
  };
  return {
    nome: "navegador",
    streaming: true,
    iniciar() {
      ativo = true;
      iniciar();
    },
    idioma(novo) {
      lang = LOCALE[novo] ?? lang;
      if (ativo) rec?.stop();
    },
    parar() {
      ativo = false;
      rec?.abort();
    },
  };
}

/**
 * STT no servidor (Whisper): grava a fala entre o início e o fim do turno e
 * envia o trecho. Não é streaming: a transcrição chega depois do fim da fala.
 */
export function sttWhisper({ mic, api, idioma, aoTexto, aoErro }) {
  let gravador = null;
  let partes = [];
  let lang = idioma;
  const tipo = ["audio/webm;codecs=opus", "audio/mp4", "audio/ogg"].find((t) => window.MediaRecorder?.isTypeSupported?.(t)) ?? "";
  return {
    nome: "servidor_whisper",
    streaming: false,
    iniciar() {
      partes = [];
      gravador = new MediaRecorder(mic.stream, tipo ? { mimeType: tipo } : undefined);
      gravador.ondataavailable = (e) => e.data.size && partes.push(e.data);
      gravador.start(250);
    },
    idioma(novo) {
      lang = novo;
    },
    /** Fecha o trecho atual e devolve o texto transcrito. */
    async concluir() {
      if (!gravador) return { texto: "", confianca: null };
      const pronto = new Promise((r) => (gravador.onstop = r));
      gravador.stop();
      await pronto;
      const blob = new Blob(partes, { type: tipo.split(";")[0] || "audio/webm" });
      this.iniciar();
      if (blob.size < 2000) return { texto: "", confianca: null };
      try {
        const r = await api.stt(blob, lang);
        aoTexto?.({ parcial: "", final: r.texto, confianca: r.confianca });
        return r;
      } catch (e) {
        aoErro?.(e.message);
        return { texto: "", confianca: null, falha: true };
      }
    },
    parar() {
      if (gravador && gravador.state !== "inactive") gravador.stop();
      gravador = null;
    },
  };
}

/** STT em streaming pelo Deepgram (WebSocket direto do navegador, token de 60 s). */
export function sttDeepgram({ mic, api, idioma, aoTexto, aoErro }) {
  let ws = null;
  let gravador = null;
  let lang = idioma;
  const abrir = async () => {
    const { token } = await api.sttToken();
    const params = new URLSearchParams({ model: "nova-3", language: LOCALE[lang] ?? "pt-BR", interim_results: "true", smart_format: "true", endpointing: "300" });
    ws = new WebSocket(`wss://api.deepgram.com/v1/listen?${params}`, ["bearer", token]);
    ws.onmessage = (m) => {
      const d = JSON.parse(m.data);
      const alt = d.channel?.alternatives?.[0];
      if (!alt) return;
      if (d.is_final) aoTexto({ parcial: "", final: alt.transcript, confianca: alt.confidence ?? null });
      else aoTexto({ parcial: alt.transcript, final: "", confianca: null });
    };
    ws.onerror = () => aoErro?.("deepgram");
    ws.onclose = () => {
      if (gravador) setTimeout(() => gravador && abrir().catch((e) => aoErro?.(e.message)), 500);
    };
    await new Promise((r, j) => ((ws.onopen = r), setTimeout(() => j(new Error("deepgram: tempo esgotado")), 5000)));
    gravador = new MediaRecorder(mic.stream, { mimeType: "audio/webm;codecs=opus" });
    gravador.ondataavailable = (e) => ws?.readyState === 1 && e.data.size && ws.send(e.data);
    gravador.start(250);
  };
  return {
    nome: "deepgram",
    streaming: true,
    async iniciar() {
      await abrir();
    },
    idioma(novo) {
      lang = novo;
      gravador?.stop();
      gravador = null;
      ws?.close();
      abrir().catch((e) => aoErro?.(e.message));
    },
    parar() {
      gravador?.stop();
      gravador = null;
      ws?.close();
    },
  };
}

// ─── TTS ──────────────────────────────────────────────────────────────────

export const ttsNavegadorSuportado = () => "speechSynthesis" in window;

/**
 * Melhor voz do navegador para o idioma: vozes neurais/online primeiro
 * ("Google", "Natural", "Neural", "Premium", "Enhanced"); as compactas do
 * sistema (mais robóticas) por último.
 */
export function vozDoNavegador(idioma) {
  const vozes = speechSynthesis.getVoices();
  const loc = LOCALE[idioma] ?? "pt-BR";
  const doIdioma = vozes.filter((v) => v.lang === loc || v.lang.replace("_", "-") === loc);
  const candidatas = doIdioma.length ? doIdioma : vozes.filter((v) => v.lang.startsWith(loc.slice(0, 2)));
  const nota = (v) => (/natural|neural/i.test(v.name) ? 4 : /premium|enhanced|aprimorad/i.test(v.name) ? 3 : /google/i.test(v.name) ? 2 : !v.localService ? 1 : 0);
  return [...candidatas].sort((a, b) => nota(b) - nota(a))[0] ?? null;
}

/**
 * Voz do navegador (reserva quando não há voz no servidor). Cada trecho é
 * dito inteiro (a fala vem em no máximo dois trechos: a primeira frase e o
 * restante), para a entonação não reiniciar a cada frase.
 */
export function ttsNavegador({ aoComecar, aoTerminar, preferencias = () => ({}) }) {
  let pendentes = 0;
  let geracao = 0;
  return {
    nome: "navegador",
    falar(trecho, idioma) {
      const g = geracao;
      const { volume = 1, velocidade = 1 } = preferencias();
      const u = new SpeechSynthesisUtterance(trecho.texto);
      const v = vozDoNavegador(idioma);
      if (v) u.voice = v;
      u.lang = LOCALE[idioma] ?? "pt-BR";
      u.rate = velocidade;
      u.volume = volume;
      pendentes++;
      u.onstart = () => g === geracao && aoComecar?.(performance.now());
      u.onend = u.onerror = () => {
        if (g !== geracao) return;
        pendentes = Math.max(0, pendentes - 1);
        if (pendentes === 0) aoTerminar?.(performance.now());
      };
      speechSynthesis.speak(u);
    },
    cancelar() {
      geracao++;
      pendentes = 0;
      speechSynthesis.cancel();
    },
    falando: () => pendentes > 0,
    volume() {},
  };
}

/**
 * Voz do servidor (ElevenLabs/OpenAI) tocada por Web Audio: cada trecho é
 * baixado assim que chega, decodificado e agendado exatamente no fim do
 * anterior (sem lacuna, sem sobreposição, volume constante). `cancelar`
 * interrompe o que está tocando, descarta o que estava agendado e aborta os
 * downloads pendentes.
 */
export function ttsServidor({ api, aoComecar, aoTerminar, preferencias = () => ({}) }) {
  let ctx = null;
  let ganho = null;
  let geracao = 0;
  let fimAgendado = 0;
  let pendentes = 0;
  let fontes = [];
  let downloads = [];
  let fila = Promise.resolve();
  const garantir = () => {
    if (!ctx) {
      ctx = new (window.AudioContext || window.webkitAudioContext)();
      ganho = ctx.createGain();
      ganho.connect(ctx.destination);
    }
    ganho.gain.value = preferencias().volume ?? 1;
    if (ctx.state === "suspended") ctx.resume().catch(() => {});
  };
  /** Toca os trechos na ordem em que foram pedidos, sem intervalo entre eles. */
  const agendar = (bytes) => {
    garantir();
    const g = geracao;
    pendentes++;
    const audio = bytes.then((buf) => ctx.decodeAudioData(buf)).catch(() => null);
    fila = fila.then(async () => {
        const buffer = await audio;
        if (g !== geracao) return;
        if (!buffer) {
          pendentes = Math.max(0, pendentes - 1);
          if (pendentes === 0) aoTerminar?.(performance.now(), { falha: true });
          return;
        }
        const fonte = ctx.createBufferSource();
        fonte.buffer = buffer;
        fonte.connect(ganho);
        const inicio = Math.max(ctx.currentTime + 0.02, fimAgendado);
        if (fimAgendado <= ctx.currentTime + 0.02) {
          const atraso = Math.max(0, (inicio - ctx.currentTime) * 1000);
          setTimeout(() => g === geracao && aoComecar?.(performance.now()), atraso);
        }
        fimAgendado = inicio + buffer.duration;
        fonte.onended = () => {
          fontes = fontes.filter((f) => f !== fonte);
          if (g !== geracao) return;
          pendentes = Math.max(0, pendentes - 1);
          if (pendentes === 0) aoTerminar?.(performance.now());
        };
        fonte.start(inicio);
        fontes.push(fonte);
      });
  };
  return {
    nome: "servidor",
    /** `trecho`: { texto, anterior, proximo } — o contexto dá continuidade à entonação. */
    falar(trecho) {
      garantir();
      const ctrl = new AbortController();
      downloads.push(ctrl);
      agendar(api.tts({ ...trecho, velocidade: preferencias().velocidade ?? 1 }, ctrl.signal).then((b) => b.arrayBuffer()));
    },
    /** Trecho que já chegou pronto no próprio pedido do turno (MP3 em base64). */
    tocarMp3(base64) {
      const bin = atob(base64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      agendar(Promise.resolve(bytes.buffer));
    },
    cancelar() {
      geracao++;
      pendentes = 0;
      for (const d of downloads) d.abort();
      downloads = [];
      for (const f of fontes) {
        try {
          f.stop();
        } catch {}
      }
      fontes = [];
      fimAgendado = 0;
      fila = Promise.resolve();
    },
    falando: () => pendentes > 0,
    volume(v) {
      if (ganho) ganho.gain.setTargetAtTime(v, ctx.currentTime, 0.05);
    },
  };
}
