/**
 * Sala do candidato: convite → explicação e privacidade → teste técnico →
 * entrevista por voz (ou texto) → conclusão → pesquisa de experiência.
 *
 * Caminho crítico de voz: fim da fala (VAD + STT em streaming) → um pedido
 * SSE → frases faladas assim que chegam. Interrupção pela fala do candidato
 * corta a voz e descarta o áudio pendente; o turno da IA continua sendo
 * gravado no servidor (a transcrição registra que houve interrupção).
 */
import { similaridade } from "../engine/texto.js";
import { criarApi, ErroSala } from "./api.js";
import { TomadaDeTurno, Trechos } from "./turnos.js";
import { abrirMicrofone, medirRuido, sttDeepgram, sttNavegador, sttNavegadorSuportado, sttWhisper, ttsNavegador, ttsNavegadorSuportado, ttsServidor } from "./voz.js";

const $ = (id) => document.getElementById(id);
const telas = ["carregando", "erro", "boas-vindas", "agendar", "teste", "conversa", "pausa", "fim"];
function mostrar(nome) {
  for (const t of telas) $(`tela-${t}`).hidden = t !== nome;
  $("conteudo").focus({ preventScroll: true });
  window.scrollTo({ top: 0 });
}
function falhar(msg) {
  $("erro-texto").textContent = msg;
  mostrar("erro");
}

const token = new URLSearchParams(location.search).get("t") ?? "";
const api = criarApi(token);
const s = {
  ctx: null,
  modalidade: "voz",
  seq: 0,
  idioma: "pt",
  ultimaFala: "",
  falaAtual: "",
  mic: null,
  stt: null,
  tts: null,
  tt: new TomadaDeTurno(),
  ocupado: false,
  pendente: null, // turno em andamento (promessa)
  legendas: true,
  mudo: false,
  finalizada: false,
  confianca: null,
  laco: null,
  medicao: null,
  turnoVoz: 0, // muda a cada interrupção: a fala ainda chegando daquele turno é descartada
  pref: { volume: 1, velocidade: 1 },
};
try {
  Object.assign(s.pref, JSON.parse(localStorage.getItem("iv_voz") ?? "{}"));
} catch {}
const preferencias = () => s.pref;

// ─── Preferências de acessibilidade ──────────────────────────────────────
try {
  if (localStorage.getItem("iv_texto_grande") === "1") {
    document.body.classList.add("texto-grande");
    $("texto-grande").checked = true;
  }
} catch {}
$("texto-grande").addEventListener("change", (e) => {
  document.body.classList.toggle("texto-grande", e.target.checked);
  try {
    localStorage.setItem("iv_texto_grande", e.target.checked ? "1" : "0");
  } catch {}
});

// ─── 1. Convite ──────────────────────────────────────────────────────────
async function carregar() {
  if (!token) return falhar("Link incompleto. Abra o endereço completo recebido no convite.");
  try {
    s.ctx = await api.contexto();
  } catch (e) {
    return falhar(e.message);
  }
  const c = s.ctx;
  s.idioma = c.idioma;
  document.documentElement.lang = { pt: "pt-BR", en: "en", es: "es" }[c.idioma] ?? "pt-BR";
  document.title = `Entrevista · ${c.vaga.cargo} · ${c.empresa.nome}`;
  if (c.empresa.cor) document.documentElement.style.setProperty("--brand", c.empresa.cor);
  $("empresa-nome").textContent = c.empresa.nome;
  $("titulo-vaga").textContent = c.vaga.cargo;
  for (const el of document.querySelectorAll(".empresa")) el.textContent = c.empresa.nome;
  $("fatos").replaceChildren(...[c.vaga.area, c.vaga.modeloTrabalho, c.vaga.localidade, c.vaga.contratacao, `Até ${new Date(c.expiraEm).toLocaleDateString("pt-BR")}`].filter(Boolean).map((t) => Object.assign(document.createElement("li"), { textContent: t })));
  for (const id of ["nome-ia", "nome-ia-2"]) $(id).textContent = c.entrevistadora;
  $("avatar").textContent = c.entrevistadora.slice(0, 1).toUpperCase();
  $("duracao").textContent = `${c.duracaoMin} minutos${c.temBlocoIdioma ? " (com uma parte curta em outro idioma)" : ""}`;
  $("aviso-empresa").textContent = c.avisoPrivacidade || "";
  $("termos-versao").textContent = `${c.termosVersao} · ${c.avisoVersao}`;
  if (!c.modalidades.includes("voz")) {
    document.querySelector('input[value="texto"]').checked = true;
    document.querySelector('input[value="voz"]').disabled = true;
  }
  if (!c.modalidades.includes("texto")) document.querySelector('input[value="texto"]').disabled = true;

  if (c.sessao?.encerrada) {
    mostrar("fim");
    return;
  }
  if (c.sessao?.podeRetomar) {
    $("consentimento").checked = true;
    $("ir-teste").disabled = false;
    $("ir-teste").textContent = "Retomar a entrevista";
    $("ir-teste").dataset.retomar = "1";
    $("ir-agendar").hidden = true;
  }
  mostrar("boas-vindas");
}

$("consentimento").addEventListener("change", (e) => ($("ir-teste").disabled = !e.target.checked));
$("ir-agendar").addEventListener("click", () => mostrar("agendar"));
for (const b of document.querySelectorAll("[data-voltar]")) b.addEventListener("click", () => mostrar("boas-vindas"));
$("confirmar-agendar").addEventListener("click", async () => {
  const v = $("quando").value;
  if (!v) return ($("agendar-status").textContent = "Escolha data e hora.");
  try {
    const r = await api.agendar(new Date(v).toISOString(), Intl.DateTimeFormat().resolvedOptions().timeZone);
    $("agendar-status").textContent = `Agendado para ${new Date(r.inicio).toLocaleString("pt-BR")}. Abra este mesmo link no horário.`;
  } catch (e) {
    $("agendar-status").textContent = e.message;
  }
});

$("ir-teste").addEventListener("click", async () => {
  s.modalidade = document.querySelector('input[name="modalidade"]:checked').value;
  if (s.modalidade === "texto") return iniciarOuRetomar();
  mostrar("teste");
  await testeTecnico();
});
$("usar-texto").addEventListener("click", () => {
  s.modalidade = "texto";
  pararVoz();
  iniciarOuRetomar();
});

// ─── 2. Teste técnico ────────────────────────────────────────────────────
function escolherProvedores() {
  const p = s.ctx.provedores;
  const aoTexto = (r) => tratarTexto(r);
  const aoErro = (e) => {
    api.evento("falha_stt", { erro: String(e).slice(0, 40), provedor: s.stt?.nome ?? "" });
    status("O reconhecimento de fala falhou. Você pode responder digitando.");
  };
  if (p.stt.includes("deepgram")) s.stt = sttDeepgram({ mic: s.mic, api, idioma: s.idioma, aoTexto, aoErro });
  else if (sttNavegadorSuportado()) s.stt = sttNavegador({ idioma: s.idioma, aoTexto, aoErro });
  else if (p.stt.includes("groq_whisper")) s.stt = sttWhisper({ mic: s.mic, api, idioma: s.idioma, aoErro });
  else s.stt = null;
  const aoComecar = (t) => {
    avatarFalando(true);
    if (s.medicao && !s.medicao.primeiroAudio) s.medicao.primeiroAudio = t;
    s.tt.iaComecou(t);
  };
  const aoTerminar = (t) => {
    avatarFalando(false);
    s.tt.iaTerminou(t);
    if (!s.finalizada) status("Sua vez. Pode falar quando quiser.");
    registrarLatencia();
    if (s.finalizada) concluir();
  };
  // Voz do servidor (ElevenLabs/OpenAI) quando configurada; senão, a melhor voz do navegador.
  if (p.tts.length) s.tts = ttsServidor({ api, aoComecar, aoTerminar: (t, info) => (info?.falha && reservaNavegador(), aoTerminar(t)), preferencias });
  else if (ttsNavegadorSuportado()) s.tts = ttsNavegador({ aoComecar, aoTerminar, preferencias });
  else s.tts = null;
}

async function testeTecnico() {
  const alerta = (m) => {
    $("teste-alerta").textContent = m;
    $("teste-alerta").hidden = !m;
  };
  alerta("");
  try {
    s.mic ??= await abrirMicrofone();
    $("mic-status").textContent = "medindo ruído…";
    const ruido = await medirRuido(s.mic);
    const limiar = s.tt.calibrar(ruido);
    $("mic-status").textContent = ruido > 0.03 ? "ambiente com ruído: prefira fone" : "funcionando";
    api.evento("teste_tecnico", { ruido: Math.round(ruido * 1000) / 1000, limiar: Math.round(limiar * 1000) / 1000 });
  } catch {
    $("mic-status").textContent = "sem acesso";
    alerta("Não conseguimos acessar o microfone. Libere o acesso nas configurações do navegador ou faça a entrevista por texto.");
    return;
  }
  const medidor = () => {
    if ($("tela-teste").hidden) return;
    $("mic-nivel").style.width = `${Math.min(100, s.mic.nivel() * 600)}%`;
    requestAnimationFrame(medidor);
  };
  medidor();
  escolherProvedores();
  if (!s.stt) {
    $("stt-status").textContent = "indisponível neste navegador";
    alerta("Este navegador não reconhece fala. Use Chrome, Edge ou Safari atualizados, ou responda por texto.");
  } else if (s.stt.streaming) {
    const eco = (r) => {
      $("stt-eco").textContent = r.final || r.parcial;
      if (r.final) $("stt-status").textContent = "funcionando";
    };
    const sttTeste = s.stt.nome === "navegador" ? sttNavegador({ idioma: s.idioma, aoTexto: eco, aoErro: () => ($("stt-status").textContent = "falhou") }) : null;
    if (sttTeste) {
      sttTeste.iniciar();
      $("comecar").addEventListener("click", () => sttTeste.parar(), { once: true });
      $("usar-texto").addEventListener("click", () => sttTeste.parar(), { once: true });
    } else $("stt-status").textContent = "pronto";
  } else $("stt-status").textContent = "transcrição ao final de cada resposta";
  if (!s.tts) alerta("Este navegador não tem voz sintética: a entrevistadora aparecerá em legendas.");
}

$("testar-som").addEventListener("click", async () => {
  if (!s.tts) escolherProvedores();
  // Teste com a mesma voz da entrevista (o servidor só sintetiza a frase fixa de teste).
  if (s.ctx.provedores.tts.length) {
    try {
      const blob = await api.ttsTeste(s.pref.velocidade);
      const a = new Audio(URL.createObjectURL(blob));
      a.volume = s.pref.volume;
      await a.play();
      return;
    } catch {}
  }
  const frase = { pt: `Oi! Eu sou a ${s.ctx.entrevistadora}, a entrevistadora de IA do Candydate. Você está me ouvindo bem?`, en: `Hi! I'm ${s.ctx.entrevistadora}, the AI interviewer from Candydate. Can you hear me well?`, es: `¡Hola! Soy ${s.ctx.entrevistadora}, la entrevistadora de IA de Candydate. ¿Me escucha bien?` }[s.idioma];
  ttsNavegador({ preferencias })?.falar({ texto: frase }, s.idioma);
});

/** Voz do servidor falhou no meio da entrevista: segue com a do navegador e registra. */
function reservaNavegador() {
  if (!ttsNavegadorSuportado() || s.tts?.nome !== "servidor") return;
  api.evento("falha_tts", { provedor: "servidor" });
  const anterior = s.tts;
  s.tts = ttsNavegador({ aoComecar: () => avatarFalando(true), aoTerminar: (t) => (avatarFalando(false), s.tts.falando() || s.tt.iaTerminou(t)), preferencias });
  anterior.cancelar();
  falar(s.ultimaFala, true);
}
$("comecar").addEventListener("click", () => iniciarOuRetomar());

// ─── 3. Conversa ─────────────────────────────────────────────────────────
function status(t) {
  $("status").textContent = t;
}
function avatarFalando(sim) {
  $("avatar").classList.toggle("falando", sim);
}
function historico(papel, texto) {
  const d = document.createElement("div");
  d.className = `msg msg--${papel}`;
  const q = Object.assign(document.createElement("span"), { className: "msg__quem", textContent: papel === "ia" ? `${s.ctx.entrevistadora} (IA)` : "Você" });
  d.append(q, document.createTextNode(texto));
  $("historico").append(d);
  $("historico").scrollTop = $("historico").scrollHeight;
}

let iniciando = false;
async function iniciarOuRetomar() {
  // Um início por vez: o clique duplo em "Começar" não cria pedido repetido.
  if (iniciando) return;
  iniciando = true;
  for (const id of ["comecar", "usar-texto", "ir-teste"]) $(id).disabled = true;
  status("Preparando a entrevista…");
  try {
    if ($("ir-teste").dataset.retomar) {
      const r = await api.retomar();
      if (r.encerrada) return mostrar("fim");
      s.seq = r.seq;
      // A pessoa pode retomar em outra modalidade (ex.: voz falhou → texto); o servidor registra a troca.
      if (r.modalidade !== s.modalidade) api.evento("modalidade", { de: r.modalidade, para: s.modalidade });
      for (const t of r.transcricao) historico(t.papel, t.texto);
      if (r.estado === "pausada") return mostrar("pausa");
      entrarNaConversa(r.ultimaFala ?? "");
      return;
    }
    const r = await api.iniciar({ consentimento: true, gravacao: false, modalidade: s.modalidade, stt: s.stt?.nome ?? "texto", tts: s.tts?.nome ?? "legendas" });
    if (r.retomar) {
      $("ir-teste").dataset.retomar = "1";
      iniciando = false;
      return iniciarOuRetomar();
    }
    s.seq = r.seq;
    entrarNaConversa(r.fala);
  } catch (e) {
    falhar(e.message);
  } finally {
    iniciando = false;
    for (const id of ["comecar", "usar-texto", "ir-teste"]) $(id).disabled = false;
  }
}

function entrarNaConversa(primeiraFala) {
  mostrar("conversa");
  const voz = s.modalidade === "voz" && s.stt;
  $("btn-mudo").hidden = !voz;
  if (voz && !s.laco) {
    s.stt.iniciar();
    // Quadros de 50 ms: VAD + decisões de turno.
    s.laco = setInterval(() => {
      if (s.mudo || $("tela-conversa").hidden) return;
      for (const a of s.tt.voz(s.mic.nivel(), performance.now())) tratarAcao(a);
    }, 50);
  }
  if (primeiraFala) {
    historico("ia", primeiraFala);
    falar(primeiraFala, true);
  }
}

function falar(texto, completo) {
  s.ultimaFala = completo ? texto : s.ultimaFala;
  if (s.legendas) $("legenda").textContent = texto;
  if (s.modalidade === "voz" && s.tts) {
    s.tts.cancelar();
    const t = new Trechos();
    for (const trecho of [...t.adicionar(texto + " "), ...t.fim()]) s.tts.falar(trecho, s.idioma);
  } else {
    status("Sua vez. Escreva a resposta abaixo.");
    if (s.finalizada) concluir();
  }
}

function tratarTexto(r) {
  // Fala reconhecida enquanto a IA fala: só vale como interrupção se não for eco da própria IA.
  if (s.tts?.falando()) {
    const ouvido = r.parcial || r.final;
    if (ouvido.split(/\s+/).length >= 3 && similaridade(ouvido, s.falaAtual) < 0.5) interromper("texto");
    else return;
  }
  if (r.final) s.confianca = r.confianca;
  s.tt.texto(r.parcial, r.final, performance.now());
  $("voce").textContent = `${(s.tt.textoFinal + " " + s.tt.parcial).trim()}`;
}

function interromper(origem) {
  if (!s.tts?.falando()) return;
  s.turnoVoz++; // o restante da fala deste turno, se ainda estiver chegando, não vai para a voz
  s.tts.cancelar(); // descarta o áudio tocando, o agendado e os downloads pendentes
  avatarFalando(false);
  s.tt.iaTerminou(performance.now());
  api.evento("interrupcao_ia", { origem, seq: s.seq });
  status("Ouvindo você…");
}

async function tratarAcao(a) {
  if (a.tipo === "interromper_ia") {
    // Só VAD (sem texto ainda): exige reconhecimento para não cortar a IA por eco.
    if (!s.stt?.streaming) interromper("voz");
    return;
  }
  if (a.tipo === "pensando") return status("Sem pressa. Estou ouvindo.");
  if (a.tipo === "silencio_longo") return status("Sem pressa. Se quiser, diga \"pode repetir\" ou responda digitando.");
  if (a.tipo === "silencio_sem_resposta") return enviar("", {});
  if (a.tipo === "fim_de_turno") {
    let texto = a.texto;
    let falhaAudio = false;
    if (s.stt.nome === "servidor_whisper") {
      status("Transcrevendo…");
      const r = await s.stt.concluir();
      texto = r.texto;
      falhaAudio = Boolean(r.falha);
      s.confianca = r.confianca;
    }
    $("voce").textContent = "";
    enviar(texto, { fimDaFala: a.fimDaFala, falhaAudio });
  }
}

async function enviar(texto, { fimDaFala = performance.now(), falhaAudio = false } = {}) {
  if (s.finalizada) return;
  if (s.pendente) await s.pendente.catch(() => {}); // turno anterior ainda chegando
  if (texto) historico("candidato", texto);
  s.tts?.cancelar();
  status("Pensando…");
  $("legenda").textContent = "";
  s.falaAtual = "";
  s.medicao = { fimDaFala, envio: performance.now(), primeiroTexto: null, primeiroAudio: null };
  const fr = new Trechos();
  const vozDoTurno = ++s.turnoVoz;
  let tentativa = 0;
  const confiancaStt = s.confianca;
  s.confianca = null;
  // A voz da entrevistadora vem no mesmo pedido do texto: o servidor sintetiza
  // cada trecho assim que ele fica pronto, sem uma segunda ida e volta.
  const pedirVoz = s.modalidade === "voz" && s.tts?.nome === "servidor";
  let vozNoTurno = false;
  const desteTurno = () => s.modalidade === "voz" && s.tts && vozDoTurno === s.turnoVoz;
  const executar = async () => {
    for (;;) {
      try {
        let recebido = "";
        const fim = await api.turno({
          texto, seqBase: s.seq, falhaAudio, confiancaStt,
          voz: pedirVoz, velocidade: s.pref.velocidade ?? 1,
          aoInicio: (d) => {
            if (d.idioma) idiomaDaFala = d.idioma;
            vozNoTurno = d.voz === true;
          },
          aoTexto: (p) => {
            s.medicao.primeiroTexto ??= performance.now();
            recebido += p;
            s.falaAtual = recebido;
            if (s.legendas) $("legenda").textContent = recebido;
            if (!vozNoTurno && desteTurno()) for (const f of fr.adicionar(p)) s.tts.falar(f, idiomaDaFala);
          },
          aoAudio: (d) => desteTurno() && s.tts.tocarMp3(d.mp3),
          // Trecho que o servidor não conseguiu sintetizar: pede de novo só ele.
          aoAudioFalha: (d) => desteTurno() && s.tts.falar({ texto: d.texto, anterior: "", proximo: "" }, idiomaDaFala),
        });
        return fim;
      } catch (e) {
        if (e instanceof ErroSala && e.status === 409) {
          // Conflito ou pausa: recarrega o estado salvo no servidor.
          const r = await api.retomar();
          s.seq = r.seq;
          if (r.estado === "pausada") mostrar("pausa");
          throw e;
        }
        if (++tentativa > 3 || (e instanceof ErroSala && e.status >= 400 && e.status < 500)) throw e;
        // O reenvio traz a fala inteira de novo: descarta o que já tinha começado a tocar.
        if (vozDoTurno === s.turnoVoz) s.tts?.cancelar();
        status("Conexão instável. Reenviando sua resposta…");
        api.evento("reconexao", { tentativa });
        await new Promise((r) => setTimeout(r, 800 * tentativa));
      }
    }
  };
  let idiomaDaFala = s.idioma;
  s.pendente = executar();
  try {
    const fim = await s.pendente;
    s.seq = fim.seq;
    s.ultimaFala = fim.fala;
    historico("ia", fim.fala);
    if (fim.idioma && fim.idioma !== s.idioma) {
      // Bloco em outro idioma: a fala já veio nele; o reconhecimento passa a ouvir esse idioma.
      idiomaDaFala = fim.idioma;
      s.idioma = fim.idioma;
      s.stt?.idioma(fim.idioma);
    }
    if (!vozNoTurno && desteTurno()) for (const f of fr.fim()) s.tts.falar(f, fim.idioma ?? s.idioma);
    if (fim.finalizada) s.finalizada = true;
    if (fim.pausada) return entrarEmPausa(false);
    if (s.modalidade !== "voz" || !s.tts) {
      status("Sua vez. Escreva a resposta abaixo.");
      if (s.finalizada) concluir();
    }
  } catch (e) {
    status(e.message || "Não foi possível enviar. Tente de novo.");
  } finally {
    s.pendente = null;
  }
}

function registrarLatencia() {
  const m = s.medicao;
  if (!m?.primeiroAudio) return;
  api.evento("latencia", {
    ms_primeiro_audio: Math.round(m.primeiroAudio - m.fimDaFala),
    ms_ate_envio: Math.round(m.envio - m.fimDaFala),
    ms_ate_primeiro_texto: m.primeiroTexto ? Math.round(m.primeiroTexto - m.envio) : -1,
    stt: s.stt?.nome ?? "texto",
    tts: s.tts?.nome ?? "legendas",
  });
  s.medicao = null;
}

$("form-texto").addEventListener("submit", (e) => {
  e.preventDefault();
  const t = $("resposta").value.trim();
  if (!t) return;
  $("resposta").value = "";
  s.tt.reiniciar();
  enviar(t, {});
});
$("btn-mudo").addEventListener("click", () => {
  s.mudo = !s.mudo;
  s.mic?.mudo(s.mudo);
  $("btn-mudo").setAttribute("aria-pressed", String(s.mudo));
  $("btn-mudo").textContent = s.mudo ? "Ativar microfone" : "Silenciar microfone";
});
$("btn-repetir").addEventListener("click", () => falar(s.ultimaFala, true));
function salvarPreferencias() {
  try {
    localStorage.setItem("iv_voz", JSON.stringify(s.pref));
  } catch {}
}
for (const id of ["volume", "volume-teste"]) {
  $(id).value = String(Math.round(s.pref.volume * 100));
  $(id).addEventListener("input", (e) => {
    s.pref.volume = Number(e.target.value) / 100;
    s.tts?.volume(s.pref.volume);
    for (const outro of ["volume", "volume-teste"]) if (outro !== id) $(outro).value = e.target.value;
    salvarPreferencias();
  });
}
for (const id of ["velocidade", "velocidade-teste"]) {
  $(id).value = String(s.pref.velocidade);
  $(id).addEventListener("change", (e) => {
    s.pref.velocidade = Number(e.target.value);
    for (const outro of ["velocidade", "velocidade-teste"]) if (outro !== id) $(outro).value = e.target.value;
    salvarPreferencias();
  });
}
$("btn-legenda").addEventListener("click", () => {
  s.legendas = !s.legendas;
  $("legenda").hidden = !s.legendas;
  $("btn-legenda").setAttribute("aria-pressed", String(s.legendas));
  $("btn-legenda").textContent = `Legendas: ${s.legendas ? "ligadas" : "desligadas"}`;
});
async function entrarEmPausa(chamar = true) {
  s.tts?.cancelar();
  if (chamar) await api.pausar().catch(() => {});
  mostrar("pausa");
}
$("btn-pausar").addEventListener("click", () => entrarEmPausa(true));
$("btn-continuar").addEventListener("click", async () => {
  try {
    const r = await api.continuar();
    s.seq = r.seq;
    entrarNaConversa("");
    falar(r.ultimaFala ?? s.ultimaFala, true);
  } catch (e) {
    status(e.message);
  }
});
$("btn-encerrar").addEventListener("click", async () => {
  if (!confirm("Encerrar a entrevista agora? O que você respondeu até aqui fica registrado.")) return;
  await api.encerrar().catch(() => {});
  s.finalizada = true;
  concluir();
});
async function pedirAjuda(e) {
  e?.preventDefault();
  const msg = prompt("Descreva rapidamente o que aconteceu (opcional):") ?? "";
  try {
    const r = await api.ajuda(msg);
    alert(r.mensagem);
  } catch (err) {
    alert(err.message);
  }
}
$("btn-ajuda").addEventListener("click", pedirAjuda);
$("link-ajuda").addEventListener("click", pedirAjuda);
$("link-exclusao").addEventListener("click", async (e) => {
  e.preventDefault();
  if (!confirm("Pedir à empresa a exclusão dos seus dados desta candidatura?")) return;
  try {
    alert((await api.solicitarExclusao()).mensagem);
  } catch (err) {
    alert(err.message);
  }
});

function pararVoz() {
  clearInterval(s.laco);
  s.laco = null;
  s.stt?.parar();
}

function concluir() {
  pararVoz();
  s.tts?.cancelar();
  s.mic?.fechar();
  mostrar("fim");
}

// ─── 4. Pesquisa de experiência ──────────────────────────────────────────
const notas = {};
for (const grupo of ["nota", "clareza"]) {
  for (let n = 1; n <= 5; n++) {
    const b = Object.assign(document.createElement("button"), { type: "button", textContent: String(n) });
    b.setAttribute("aria-pressed", "false");
    b.setAttribute("aria-label", `${n} de 5`);
    b.addEventListener("click", () => {
      notas[grupo] = n;
      for (const x of $(grupo).children) x.setAttribute("aria-pressed", String(x === b));
    });
    $(grupo).append(b);
  }
}
$("form-pesquisa").addEventListener("submit", async (e) => {
  e.preventDefault();
  if (!notas.nota) return ($("pesquisa-status").textContent = "Escolha uma nota geral.");
  try {
    await api.pesquisa({ nota: notas.nota, clareza: notas.clareza, comentario: $("comentario").value });
    $("pesquisa-status").textContent = "Obrigado pela avaliação.";
    e.target.querySelector("button[type=submit]").disabled = true;
  } catch (err) {
    $("pesquisa-status").textContent = err.message;
  }
});

addEventListener("offline", () => status("Sem conexão. Suas respostas salvas não se perdem; aguarde a volta da internet."));
addEventListener("online", () => {
  status("Conexão restabelecida.");
  api.evento("reconexao", { origem: "navegador" });
});

